import sys

def solve(s: str) -> int:
    if not s:
        return 0
    need = len(set(s))
    freq = {}
    left = 0
    formed = 0
    best = len(s) + 1
    for right, ch in enumerate(s):
        freq[ch] = freq.get(ch, 0) + 1
        if freq[ch] == 1:
            formed += 1
        while formed == need:
            best = min(best, right - left + 1)
            lch = s[left]
            freq[lch] -= 1
            if freq[lch] == 0:
                formed -= 1
            left += 1
    return best

s = sys.stdin.readline().strip()
print(solve(s))

