import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.hasNextLine() ? sc.nextLine().trim() : "";
        Deque<Character> stack = new ArrayDeque<>();
        int unmatched = 0;
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else {
                char need = (c == ')') ? '(' : (c == ']') ? '[' : '{';
                if (!stack.isEmpty() && stack.peek() == need) {
                    stack.pop();
                } else {
                    unmatched++;
                }
            }
        }
        int removals = unmatched + stack.size();
        if (removals == 0) System.out.println("VALID");
        else System.out.println("INVALID " + removals);
    }
}

